/* ==== INTERFACE ====
   token  --bg #F4F6F2               整幅画面唯一底色（叶绿体透光冷灰绿纸底）
   token  --text #152119             最深主文字｜标题、正文成句、最高对比度
   token  --muted #58695E            说明文字、次要标签、单位符号（对比底色 5.2:1）
   token  --rule #BAC4BA             坐标轴、刻度线、分栏分隔线（严禁用于边框包块）
   token  --focus #167440            主语义色｜叶绿体光合作用主通道、同化流动、当前选中状态（深浓叶绿）
   token  --photon #D9730D           锐利强调色（明度差 31pp）｜入射激发光子、高能磷酸键、警示异常点（琥珀激发电）
   token  --fs-h1 34px               页标题
   token  --fs-h2 22px               区块标题
   token  --fs-lead 19px             导语
   token  --fs-body 18px             正文
   token  --fs-sec 16px              次级成句
   token  --fs-label 15px            标签与控件标注
   token  --fs-tick 13px             纯数字刻度与图表下标
   token  --font-sans                无衬线主排版字体
   token  --font-mono                数据、公式、测量读数等宽字体
   版心   1488×844                   #stage 已含 padding
   论点   光合作用是植物叶绿体内以光子打破化学键的高能生化过程，全套采用透光微绿白底承托极深墨绿文字，以沉稳深叶绿（--focus）扛起95%的生化反应结构主线，仅用极小面积锐利琥珀橙（--photon）作为光能激发冲量，杜绝暗底发光与平均分色。
   材质   生物解剖台浸润滤纸：平整微冷的高明度纤维基底，搭配高反差硬质油墨刻线，无任何投影与外发光。
   签名   反应链路双轨标记：以深叶绿实线标示物质流转，仅在光激发或能量跃迁节点附着高饱和琥珀橙冲量点。
   禁令   1. 严禁使用发光阴影或 backdrop-blur 模拟荧光效果；2. 严禁出现任何承载区块底色的卡片或面板层，版面划分仅依赖留白与 --rule 标尺线；3. 严禁增加第三种高饱和语义色破坏单主色加小面积冲量的层级。
   修订   原本会为叶黄素、类胡萝卜素分别设定黄色与红色导致四色平均分色，现全部统一归纳为深叶绿反应链与单点琥珀光能跃迁，明度跨度拉大至 31pp。
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  --bg: #F4F6F2;
  --text: #152119;
  --muted: #58695E;
  --rule: #BAC4BA;

  --focus: #167440;
  --photon: #D9730D;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --lh-tight: 1.25;
  --lh-body: 1.5;

  --font-sans: "Noto Sans CJK SC", "Noto Sans Display", "PT Sans", sans-serif;
  --font-mono: "Noto Sans Mono", "LM Mono 10", monospace;

  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --dur-fast: 160ms;
  --dur-base: 240ms;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --dur-fast: 0ms;
    --dur-base: 0ms;
  }
}
